"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[413],{7205:e=>{e.exports=JSON.parse('[{"name":"Daikin","family":"Climatisation","image":"/btm-fun/assets/brands-color/daikin.svg","scale":1},{"name":"e.l.m. leblanc","family":"Chauffage","image":"/btm-fun/assets/brands-color/elm-leblanc-legacy.svg","scale":1},{"name":"Mitsubishi Electric","family":"Climatisation","image":"/btm-fun/assets/brands-color/mitsubishi-electric.svg","scale":1},{"name":"Toshiba","family":"Climatisation","image":"/btm-fun/assets/brands-color/toshiba.svg","scale":1},{"name":"GROHE","family":"Plomberie sanitaire","image":"/btm-fun/assets/brands-color/grohe.svg","scale":1},{"name":"SFA","family":"Plomberie sanitaire","image":"/btm-fun/assets/brands-color/sfa-legacy.svg","scale":1},{"name":"Jacob Delafon","family":"Plomberie sanitaire","image":"/btm-fun/assets/brands-color/jacob-delafon.svg","scale":1},{"name":"Atlantic","family":"Chauffage / chauffe-eau","image":"/btm-fun/assets/brands-color/atlantic-legacy.svg","scale":1},{"name":"Geberit","family":"Plomberie sanitaire","image":"/btm-fun/assets/brands-color/geberit.svg","scale":1},{"name":"Roca","family":"Plomberie sanitaire","image":"/btm-fun/assets/brands-color/roca.svg","scale":1},{"name":"Fleck","family":"Chauffe-eau","image":"/btm-fun/assets/brands-color/fleck.svg","scale":1},{"name":"Carrier","family":"Climatisation","image":"/btm-fun/assets/brands-color/carrier.svg","scale":1},{"name":"LG","family":"Climatisation","image":"/btm-fun/assets/brands-color/lg.svg","scale":1},{"name":"Samsung","family":"Climatisation","image":"/btm-fun/assets/brands-color/samsung.svg","scale":1},{"name":"Panasonic","family":"Climatisation","image":"/btm-fun/assets/brands-color/panasonic.svg","scale":1},{"name":"Hitachi","family":"Climatisation","image":"/btm-fun/assets/brands-color/hitachi.svg","scale":1},{"name":"Gree","family":"Climatisation","image":"/btm-fun/assets/brands-color/gree.svg","scale":1}]')},7601:(e,t,i)=>{i.d(t,{$p:()=>a,En:()=>r,JJ:()=>l,dt:()=>n,hU:()=>o,si:()=>s});let a=[{slug:"plomberie",title:"La plomberie, dans tous ses d\xe9tails.",family:"Plomberie",eyebrow:"D\xc9PANNAGE \xb7 INSTALLATION \xb7 R\xc9NOVATION",lead:"Une fuite \xe0 r\xe9parer. Une salle de bains \xe0 imaginer. Un r\xe9seau \xe0 remettre en \xe9tat. Votre plomberie m\xe9rite une r\xe9ponse adapt\xe9e.",intro:"La plomberie accompagne tous les usages de votre logement : eau potable, eau chaude, sanitaires et \xe9vacuations. Nous abordons chaque besoin dans son ensemble, du d\xe9faut visible \xe0 l’\xe9tat des raccordements, pour choisir une r\xe9paration ou une installation coh\xe9rente.",image:"/btm-fun/assets/bath.webp",offers:[{title:"D\xe9pannage et recherche de fuite",body:"Robinet qui goutte, tuyau endommag\xe9, infiltration ou perte de pression : localiser l’origine avant d’intervenir."},{title:"Sanitaires et robinetterie",body:"Pose et remplacement de WC, lavabos, \xe9viers, mitigeurs et \xe9quipements de douche."},{title:"R\xe9seaux et \xe9vacuations",body:"Raccordements, r\xe9paration de tuyauterie, d\xe9bouchage et remplacement de canalisations."},{title:"Salle de bains",body:"R\xe9novation des \xe9quipements, adaptation des arriv\xe9es et \xe9vacuations, coordination des finitions."}],detail:[{title:"R\xe9parer au bon endroit",body:"Un sympt\xf4me ne suffit pas \xe0 choisir une solution. Nous examinons les raccordements, les joints, l’\xe9tat du mat\xe9riau et les usages concern\xe9s avant de vous pr\xe9senter les travaux utiles."},{title:"Installer pour durer",body:"La compatibilit\xe9 des \xe9quipements, leur accessibilit\xe9 pour l’entretien et la qualit\xe9 des raccordements comptent autant que leur apparence. Le projet pr\xe9voit \xe9galement les essais d’\xe9tanch\xe9it\xe9 et le contr\xf4le des \xe9vacuations."},{title:"Pour chaque type de b\xe2timent",body:"Appartement, maison, parties communes ou local professionnel : les acc\xe8s, les contraintes du r\xe9seau et les horaires de travaux sont pris en compte lors de la pr\xe9paration."}],faq:[{q:"Puis-je demander une petite r\xe9paration ?",a:"Oui. D\xe9crivez simplement le probl\xe8me et l’\xe9quipement concern\xe9. Le premier \xe9change permet de pr\xe9parer une intervention adapt\xe9e."},{q:"Faut-il conna\xeetre l’origine de la fuite ?",a:"Non. Les signes observ\xe9s suffisent : emplacement de l’eau, moment o\xf9 elle appara\xeet et \xe9quipements touch\xe9s. Une photo peut aider \xe0 pr\xe9parer le diagnostic."}]},{slug:"plombier-paris",title:"Une urgence ? Gardons les choses simples.",family:"Plomberie",eyebrow:"D\xc9PANNAGE PLOMBERIE \xc0 PARIS",lead:"Fuite, canalisation bouch\xe9e ou absence d’eau chaude : contactez directement BTM-PRO pour expliquer la situation et v\xe9rifier les possibilit\xe9s d’intervention.",intro:"Lorsqu’un probl\xe8me bloque votre quotidien, le premier \xe9change doit aller \xe0 l’essentiel : ce qui se passe, o\xf9 vous \xeates et ce qui a d\xe9j\xe0 \xe9t\xe9 coup\xe9 ou prot\xe9g\xe9. Le d\xe9lai et les conditions d’intervention sont confirm\xe9s directement avec l’\xe9quipe.",urgent:!0,offers:[{title:"Fuite et d\xe9g\xe2t des eaux",body:"Tuyaux, raccords, robinets et joints : recherche de l’origine et remise en \xe9tat apr\xe8s diagnostic."},{title:"WC ou \xe9vacuation bouch\xe9s",body:"Identifier si l’obstruction concerne un appareil, une canalisation ou une colonne commune."},{title:"Sanitaires et chasse d’eau",body:"R\xe9paration de m\xe9canisme, d\xe9faut d’\xe9tanch\xe9it\xe9, remplacement de joints et raccordements."},{title:"Plus d’eau chaude",body:"Contr\xf4le des sympt\xf4mes et orientation vers une r\xe9paration de ballon ou de r\xe9seau."}],detail:[{title:"Avant l’arriv\xe9e de l’artisan",body:"Si vous pouvez acc\xe9der sans risque \xe0 une vanne clairement identifi\xe9e, coupez l’alimentation concern\xe9e. Prot\xe9gez vos biens et \xe9vitez d’utiliser l’\xe9quipement touch\xe9. Ne manipulez pas d’installation \xe9lectrique mouill\xe9e."},{title:"Un diagnostic avant les travaux",body:"L’artisan examine la panne, explique la solution propos\xe9e et pr\xe9sente le devis. Le travail commence apr\xe8s votre accord : r\xe9paration, remplacement de la pi\xe8ce ou intervention sur la canalisation."},{title:"V\xe9rifier que le probl\xe8me est r\xe9solu",body:"La remise en eau, le contr\xf4le de l’\xe9tanch\xe9it\xe9 et l’essai de l’\xe9quipement permettent de v\xe9rifier le r\xe9sultat. Les observations utiles pour la suite vous sont expliqu\xe9es."}],faq:[{q:"Quel est le d\xe9lai d’intervention ?",a:"Il d\xe9pend du lieu, du probl\xe8me et de la disponibilit\xe9 de l’\xe9quipe. Appelez pour obtenir une confirmation adapt\xe9e \xe0 votre situation."},{q:"Une demande en ligne confirme-t-elle un rendez-vous ?",a:"Non. Elle permet de transmettre votre besoin. Le cr\xe9neau, le d\xe9lai et les conditions doivent \xeatre confirm\xe9s avec BTM-PRO."}]},{slug:"depannage-plomberie-et-fuites-eau",title:"Une fuite rep\xe9r\xe9e. Une solution expliqu\xe9e.",family:"Plomberie",eyebrow:"RECHERCHE & R\xc9PARATION DE FUITES",lead:"Une trace d’humidit\xe9, un raccord qui fuit ou une consommation inhabituelle : identifier la cause permet de r\xe9parer utilement.",intro:"Les fuites visibles et les infiltrations cach\xe9es ne se traitent pas de la m\xeame fa\xe7on. La recherche tient compte du r\xe9seau, du support et des indices disponibles afin de limiter les ouvertures inutiles.",offers:[{title:"Fuites visibles",body:"Contr\xf4le des joints, robinets d’arr\xeat, raccords et tuyaux accessibles."},{title:"Infiltrations et humidit\xe9",body:"Rep\xe9rage des signes, des arriv\xe9es d’eau et des \xe9vacuations susceptibles d’\xeatre en cause."},{title:"Cuivre, PER et multicouche",body:"R\xe9paration ou remplacement selon le mat\xe9riau : raccordements, soudure cuivre et brasure lorsque la situation le n\xe9cessite."},{title:"Contr\xf4le apr\xe8s r\xe9paration",body:"Remise en eau progressive et v\xe9rification de la zone trait\xe9e."}],detail:[{title:"Rassembler les bons indices",body:"Pr\xe9cisez l’emplacement, la fr\xe9quence et le moment o\xf9 l’eau appara\xeet. Une photo de la zone et du raccordement aide \xe0 pr\xe9parer la visite, sans remplacer le diagnostic sur place."},{title:"Choisir une r\xe9paration adapt\xe9e",body:"Un joint us\xe9, une fissure et un d\xe9faut de raccord demandent des solutions diff\xe9rentes. La proposition pr\xe9cise les pi\xe8ces concern\xe9es, l’acc\xe8s n\xe9cessaire et les \xe9ventuelles finitions \xe0 pr\xe9voir."},{title:"Limiter les r\xe9cidives",body:"L’\xe9tat des \xe9l\xe9ments voisins et les contraintes du r\xe9seau sont examin\xe9s. Si la r\xe9paration ponctuelle ne suffit pas, les travaux compl\xe9mentaires sont expliqu\xe9s avant d\xe9cision."}],faq:[{q:"Faut-il casser un mur pour trouver une fuite ?",a:"Pas syst\xe9matiquement. L’acc\xe8s d\xe9pend du r\xe9seau et de la localisation du d\xe9faut. Selon le diagnostic, la d\xe9tection acoustique, l’imagerie thermique ou un gaz traceur peuvent aider \xe0 localiser la fuite. La m\xe9thode est confirm\xe9e apr\xe8s examen."},{q:"Puis-je joindre une photo ?",a:"Oui, vous pouvez ajouter jusqu’\xe0 trois photos dans votre demande pour montrer l’\xe9quipement et la zone concern\xe9e."}]},{slug:"wc-sanitaires-paris",title:"Des sanitaires qui fonctionnent. Tout simplement.",family:"Plomberie",eyebrow:"WC \xb7 LAVABOS \xb7 DOUCHES \xb7 SANITAIRES",lead:"Installer, r\xe9parer ou remplacer vos \xe9quipements sanitaires avec des raccordements adapt\xe9s \xe0 votre logement.",intro:"Un \xe9quipement sanitaire doit s’int\xe9grer \xe0 l’espace disponible, au r\xe9seau existant et \xe0 vos usages. La pr\xe9paration permet de v\xe9rifier l’alimentation, l’\xe9vacuation, les fixations et l’acc\xe8s pour la maintenance.",image:"/btm-fun/assets/wc.webp",offers:[{title:"WC et chasse d’eau",body:"R\xe9paration de m\xe9canisme, remplacement de joints, pose de WC au sol ou suspendus."},{title:"Lavabos et \xe9viers",body:"Pose de vasques et meubles, raccordements, siphons et \xe9vacuations."},{title:"Douche et baignoire",body:"Installation ou remplacement des \xe9quipements et adaptation de la robinetterie."},{title:"R\xe9novation sanitaire",body:"Pr\xe9parer les nouvelles implantations et harmoniser les \xe9quipements de la pi\xe8ce."}],detail:[{title:"V\xe9rifier la faisabilit\xe9",body:"Un WC suspendu n\xe9cessite un support et des acc\xe8s de maintenance adapt\xe9s. Une nouvelle douche demande une \xe9vacuation et une \xe9tanch\xe9it\xe9 coh\xe9rentes. Ces points sont \xe9tudi\xe9s avant le choix d\xe9finitif."},{title:"Prendre soin de l’existant",body:"La d\xe9pose et la pose sont pr\xe9par\xe9es en tenant compte des rev\xeatements et des r\xe9seaux. Les reprises n\xe9cessaires sont identifi\xe9es dans la proposition de travaux."},{title:"Tester chaque usage",body:"D\xe9bit, remplissage, vidage et \xe9tanch\xe9it\xe9 sont v\xe9rifi\xe9s apr\xe8s raccordement. L’acc\xe8s aux robinets d’arr\xeat et aux m\xe9canismes reste un point essentiel."}],faq:[{q:"Pouvez-vous remplacer uniquement la chasse d’eau ?",a:"Oui, lorsque le r\xe9servoir et les pi\xe8ces compatibles permettent une r\xe9paration adapt\xe9e. Le diagnostic pr\xe9cise ce qui doit \xeatre remplac\xe9."},{q:"Le WC suspendu convient-il \xe0 tout logement ?",a:"Sa faisabilit\xe9 d\xe9pend du support, de l’espace disponible et du r\xe9seau d’\xe9vacuation. Une visite permet de v\xe9rifier ces conditions."}]},{slug:"remplacement-installation-robinets-mitigeurs",title:"Le bon robinet. Le bon raccordement.",family:"Plomberie",eyebrow:"ROBINETTERIE & MITIGEURS",lead:"Un robinet qui fuit ou un nouvel \xe9quipement \xe0 installer : une robinetterie choisie pour votre confort et votre installation.",intro:"Mitigeur de cuisine, robinet de lavabo ou commande de douche : le remplacement tient compte de l’implantation, de la pression, des raccordements et de l’entretien futur.",offers:[{title:"Cuisine et lavabo",body:"Remplacement de mitigeurs, flexibles, raccordements et joints accessibles."},{title:"Douche et baignoire",body:"Installation de robinets, colonnes et commandes compatibles avec l’existant."},{title:"Cartouches et m\xe9canismes",body:"Diagnostic d’une fuite ou d’un r\xe9glage d\xe9fectueux avant de remplacer tout l’\xe9quipement."},{title:"Robinets d’arr\xeat",body:"V\xe9rification et remplacement des organes d’isolement n\xe9cessaires \xe0 la maintenance."}],detail:[{title:"R\xe9parer ou remplacer ?",body:"La disponibilit\xe9 des pi\xe8ces, l’\xe9tat du corps du robinet et le type de d\xe9faut orientent le choix. Une cartouche ou un joint peut parfois suffire ; un \xe9quipement d\xe9grad\xe9 peut n\xe9cessiter un remplacement."},{title:"V\xe9rifier la compatibilit\xe9",body:"Entraxe, hauteur, profondeur, flexibles et pression doivent correspondre aux usages et aux raccordements. Le mod\xe8le retenu doit permettre une pose fiable et un entretien accessible."},{title:"Contr\xf4ler le fonctionnement",body:"Les raccordements sont v\xe9rifi\xe9s apr\xe8s remise en eau. La temp\xe9rature, le d\xe9bit et la fermeture sont test\xe9s, avec une attention particuli\xe8re \xe0 l’\xe9tanch\xe9it\xe9 sous le meuble."}],faq:[{q:"Puis-je fournir le robinet ?",a:"Oui. Communiquez sa r\xe9f\xe9rence avant la visite pour v\xe9rifier la compatibilit\xe9 et pr\xe9ciser les conditions de pose."},{q:"Un robinet qui goutte doit-il \xeatre chang\xe9 ?",a:"Pas toujours. L’origine peut \xeatre un joint ou une cartouche. L’\xe9tat de l’\xe9quipement et les pi\xe8ces disponibles d\xe9terminent la solution."}]},{slug:"debouchage-canalisations-evacuations-obstruees",title:"Retrouver une \xe9vacuation fluide.",family:"Assainissement",eyebrow:"D\xc9BOUCHAGE DE CANALISATIONS",lead:"\xc9vier, douche, WC ou r\xe9seau collectif : comprendre l’obstruction pour choisir le bon d\xe9bouchage.",intro:"Une eau qui s’\xe9coule lentement, des bruits inhabituels ou un refoulement peuvent avoir plusieurs origines. La localisation du bouchon et l’\xe9tat de la canalisation d\xe9terminent la m\xe9thode \xe0 employer.",offers:[{title:"\xc9viers et lavabos",body:"Siphons, raccords et canalisations de cuisine ou salle de bains."},{title:"WC et douches",body:"D\xe9bouchage adapt\xe9 aux \xe9quipements et au r\xe9seau d’\xe9vacuation."},{title:"Colonnes et collecteurs",body:"Diagnostic des parties communes et coordination avec le gestionnaire."},{title:"Curage et inspection",body:"Nettoyage ou inspection cam\xe9ra lorsque l’\xe9tat et l’acc\xe8s du r\xe9seau le justifient."}],detail:[{title:"Reconna\xeetre un probl\xe8me de r\xe9seau",body:"Si plusieurs appareils refoulent ensemble, l’obstruction peut \xeatre plus loin dans la canalisation. Signalez les \xe9quipements concern\xe9s et les interventions d\xe9j\xe0 tent\xe9es."},{title:"Choisir la m\xe9thode utile",body:"Le furet, le nettoyage m\xe9canique ou l’hydrocurage ne r\xe9pondent pas aux m\xeames situations. L’intervention prend en compte le mat\xe9riau et la r\xe9sistance de la canalisation."},{title:"Pr\xe9venir le prochain bouchon",body:"Les d\xe9p\xf4ts de graisse, les lingettes et les cheveux favorisent les obstructions. Apr\xe8s intervention, les recommandations portent sur les usages et l’entretien du r\xe9seau concern\xe9."}],faq:[{q:"Dois-je utiliser un d\xe9boucheur chimique ?",a:"\xc9vitez d’en ajouter avant la visite. Si un produit a d\xe9j\xe0 \xe9t\xe9 utilis\xe9, informez l’artisan pour pr\xe9parer une intervention adapt\xe9e."},{q:"Le bouchon revient souvent : que faire ?",a:"Une inspection ou un nettoyage du r\xe9seau peut \xeatre utile. Le diagnostic recherche une cause r\xe9currente plut\xf4t que de traiter seulement le sympt\xf4me."}]},{slug:"chauffage",title:"Un int\xe9rieur bien chauff\xe9. Un syst\xe8me bien pens\xe9.",family:"Chauffage",eyebrow:"INSTALLATION \xb7 ENTRETIEN \xb7 D\xc9PANNAGE",lead:"Chaudi\xe8re, radiateurs, plancher chauffant ou pompe \xe0 chaleur : choisir et entretenir le chauffage adapt\xe9 \xe0 votre b\xe2timent.",intro:"La qualit\xe9 du chauffage d\xe9pend de l’\xe9quipement, du r\xe9seau de distribution et des r\xe9glages. Nous examinons le besoin du logement et l’installation existante pour proposer une intervention coh\xe9rente.",image:"/btm-fun/assets/heating.webp",offers:[{title:"Chaudi\xe8res et d\xe9pannage",body:"Recherche de panne, r\xe9paration et remplacement des \xe9quipements selon diagnostic."},{title:"Radiateurs et r\xe9gulation",body:"Pose de radiateurs et s\xe8che-serviettes, purge, robinets thermostatiques et r\xe9glage des \xe9quipements."},{title:"R\xe9seaux de chauffage",body:"Chauffage central, planchers et murs chauffants ; nettoyage et d\xe9sembouage adapt\xe9s."},{title:"Entretien et suivi",body:"Maintenance des \xe9quipements et pr\xe9paration d’un contrat selon vos besoins."}],detail:[{title:"Partir du besoin r\xe9el",body:"Surface, isolation, usages et contraintes techniques orientent le choix. Un projet se pr\xe9pare avec les caract\xe9ristiques du b\xe2timent et la compatibilit\xe9 du syst\xe8me envisag\xe9."},{title:"Am\xe9liorer le confort au quotidien",body:"Une pi\xe8ce trop froide ou des temp\xe9ratures irr\xe9guli\xe8res ne n\xe9cessitent pas toujours un changement complet. La distribution, les r\xe9glages et l’\xe9tat du r\xe9seau peuvent expliquer le probl\xe8me."},{title:"Organiser l’entretien",body:"Le suivi pr\xe9voit les contr\xf4les propres \xe0 l’\xe9quipement et les acc\xe8s n\xe9cessaires. Une panne r\xe9currente, un bruit nouveau ou un d\xe9faut affich\xe9 sont \xe0 signaler lors de l’\xe9change."}],faq:[{q:"Intervenez-vous sur un chauffage existant ?",a:"Oui, pour le diagnostic, l’entretien, les r\xe9parations ou la modernisation. Pr\xe9cisez le type et la r\xe9f\xe9rence de votre \xe9quipement."},{q:"Puis-je demander une \xe9tude de remplacement ?",a:"Oui. La demande permet de pr\xe9parer un \xe9change sur vos usages, vos contraintes et les solutions envisageables."}]},{slug:"renovation-et-modernisation-des-systemes-de-chauffage",title:"Faire \xe9voluer votre chauffage avec m\xe9thode.",family:"Chauffage",eyebrow:"R\xc9NOVATION & MODERNISATION",lead:"Remplacer un \xe9quipement, optimiser la r\xe9gulation ou revoir le r\xe9seau : un projet de chauffage adapt\xe9 \xe0 l’existant.",intro:"Moderniser un chauffage commence par comprendre ce qui fonctionne, ce qui limite le confort et ce que le b\xe2timent peut accueillir. La solution doit \xeatre compatible avec la distribution de chaleur et les contraintes d’installation.",image:"/btm-fun/assets/heating.webp",offers:[{title:"Remplacement de chaudi\xe8re",body:"\xc9tude du raccordement, de l’\xe9vacuation et de la compatibilit\xe9 avec le r\xe9seau."},{title:"Pompe \xe0 chaleur",body:"Examen des besoins, de l’implantation et du syst\xe8me de distribution existant."},{title:"R\xe9gulation et thermostats",body:"Adapter les commandes aux usages et aux caract\xe9ristiques des pi\xe8ces."},{title:"Distribution de chaleur",body:"Radiateurs, plancher chauffant, robinets et nettoyage du circuit."}],detail:[{title:"Comparer des solutions pertinentes",body:"Le dimensionnement, l’entretien et les contraintes du b\xe2timent comptent autant que le prix d’achat. Les options sont expliqu\xe9es \xe0 partir de vos besoins, sans promettre une \xe9conomie identique pour tous."},{title:"Pr\xe9parer la transition",body:"La d\xe9pose, les raccordements, les acc\xe8s et l’immobilisation \xe9ventuelle du chauffage sont identifi\xe9s en amont. Les \xe9tapes du chantier sont pr\xe9cis\xe9es dans la proposition."},{title:"Accompagner la prise en main",body:"Apr\xe8s mise en service, les commandes et les r\xe9glages courants vous sont pr\xe9sent\xe9s. L’entretien n\xe9cessaire est expliqu\xe9 pour pr\xe9server le fonctionnement de l’installation."}],faq:[{q:"Faut-il changer tous les radiateurs ?",a:"Pas syst\xe9matiquement. Leur compatibilit\xe9 avec le futur \xe9quipement doit \xeatre v\xe9rifi\xe9e lors de l’\xe9tude."},{q:"Des aides sont-elles possibles ?",a:"Cela d\xe9pend du projet, du logement et des conditions en vigueur. L’\xe9ligibilit\xe9 et les qualifications n\xe9cessaires doivent \xeatre v\xe9rifi\xe9es avant tout engagement."}]},{slug:"ballon-deau-chaude-installation-et-reparation",title:"L’eau chaude, quand vous en avez besoin.",family:"Chauffage",eyebrow:"CHAUFFE-EAU & BALLONS D’EAU CHAUDE",lead:"Panne, fuite ou remplacement : pr\xe9parer une solution d’eau chaude adapt\xe9e \xe0 votre foyer.",intro:"La capacit\xe9 du ballon, son emplacement, l’alimentation et l’\xe9tat du r\xe9seau influencent le confort et la faisabilit\xe9 d’un remplacement. La recherche de panne permet d’\xe9viter un remplacement inutile.",offers:[{title:"Diagnostic de panne",body:"Absence d’eau chaude, temp\xe9rature irr\xe9guli\xe8re ou d\xe9faut de fonctionnement."},{title:"Fuite et pi\xe8ces d’usure",body:"Contr\xf4le des raccords, du groupe de s\xe9curit\xe9 et de l’\xe9tat visible du ballon."},{title:"Remplacement et installation",body:"Choix de la capacit\xe9, fixation, raccordements et remise en service."},{title:"Entretien et d\xe9tartrage",body:"Intervention selon le mod\xe8le, l’\xe9tat et les recommandations du fabricant."}],detail:[{title:"Identifier les sympt\xf4mes",body:"Indiquez si le d\xe9faut concerne toute l’eau chaude, la temp\xe9rature ou seulement le d\xe9bit. La r\xe9f\xe9rence et une photo de l’appareil permettent de pr\xe9parer la visite."},{title:"Choisir la capacit\xe9 et l’implantation",body:"Le nombre d’utilisateurs, les usages et l’espace disponible orientent le choix. Les acc\xe8s de maintenance et les raccordements sont \xe9galement examin\xe9s."},{title:"Contr\xf4ler la remise en service",body:"Les raccordements et les dispositifs associ\xe9s sont v\xe9rifi\xe9s. Le temps de chauffe et les r\xe9glages d\xe9pendent du mod\xe8le : les indications utiles vous sont expliqu\xe9es."}],faq:[{q:"Le ballon doit-il \xeatre chang\xe9 au bout de dix ans ?",a:"L’\xe2ge seul ne suffit pas. Son \xe9tat, les d\xe9fauts constat\xe9s et la disponibilit\xe9 des pi\xe8ces orientent la d\xe9cision."},{q:"Que faire si le ballon fuit ?",a:"Prot\xe9gez la zone et \xe9vitez toute manipulation \xe9lectrique \xe0 proximit\xe9 de l’eau. Contactez un professionnel pour identifier la fuite et les mesures adapt\xe9es."}]},{slug:"climatisation-paris",title:"Le confort, en toute saison.",family:"Climatisation",eyebrow:"CLIMATISATION & SOLUTIONS R\xc9VERSIBLES",lead:"Installation, entretien et d\xe9pannage de climatisation pour votre logement ou vos locaux professionnels.",intro:"Une installation r\xe9ussie part de vos usages : pi\xe8ces \xe0 traiter, isolation, bruit, implantation et entretien. Le syst\xe8me est choisi en tenant compte du b\xe2timent et de ses contraintes.",offers:[{title:"Monosplit et multisplit",body:"Une ou plusieurs unit\xe9s int\xe9rieures selon les pi\xe8ces et les besoins."},{title:"Climatisation gainable",body:"Une solution int\xe9gr\xe9e lorsque les volumes et les acc\xe8s permettent son installation."},{title:"Pompe \xe0 chaleur r\xe9versible",body:"\xc9tude d’un \xe9quipement capable de chauffer et de rafra\xeechir selon ses caract\xe9ristiques."},{title:"Syst\xe8mes professionnels",body:"Solutions adapt\xe9es aux bureaux et locaux, dont les syst\xe8mes VRV selon projet."}],detail:[{title:"\xc9tudier l’implantation",body:"Les unit\xe9s, les liaisons, l’\xe9vacuation des condensats et l’acc\xe8s pour l’entretien doivent \xeatre pr\xe9vus. Les contraintes de copropri\xe9t\xe9 ou de fa\xe7ade sont \xe0 examiner avant les travaux."},{title:"Entretenir pour garder le confort",body:"Nettoyage des filtres, contr\xf4le de l’\xe9coulement et diagnostic des d\xe9fauts permettent de suivre l’\xe9tat du syst\xe8me. Les op\xe9rations sur le circuit frigorifique n\xe9cessitent un intervenant habilit\xe9."},{title:"Comprendre les r\xe9glages",body:"Le mode de fonctionnement, les temp\xe9ratures de consigne et les programmes sont pr\xe9sent\xe9s lors de la mise en service. Le dimensionnement et les usages influencent la consommation."}],faq:[{q:"Quel syst\xe8me choisir pour plusieurs pi\xe8ces ?",a:"Le multisplit et le gainable r\xe9pondent \xe0 des configurations diff\xe9rentes. Une \xe9tude des pi\xe8ces, de l’isolation et des possibilit\xe9s d’implantation permet de comparer les options."},{q:"La climatisation fait-elle aussi du chauffage ?",a:"Les syst\xe8mes r\xe9versibles peuvent chauffer et rafra\xeechir. Les performances et les limites d\xe9pendent du mod\xe8le et des conditions d’utilisation."}]},{slug:"assainissement",title:"Des r\xe9seaux sains. Un quotidien serein.",family:"Assainissement",eyebrow:"D\xc9BOUCHAGE \xb7 CURAGE \xb7 INSPECTION",lead:"Entretenir, diagnostiquer et remettre en \xe9tat les r\xe9seaux d’\xe9vacuation de votre b\xe2timent.",intro:"Le r\xe9seau d’assainissement \xe9vacue les eaux us\xe9es. Les d\xe9p\xf4ts, les d\xe9fauts de canalisation et les obstructions peuvent perturber son fonctionnement. Une intervention adapt\xe9e commence par comprendre le r\xe9seau et les acc\xe8s.",offers:[{title:"D\xe9bouchage et hydrocurage",body:"Traitement des obstructions et nettoyage haute pression lorsque le r\xe9seau le permet."},{title:"Inspection cam\xe9ra",body:"Rep\xe9rage de d\xe9p\xf4ts, d\xe9fauts et zones difficiles d’acc\xe8s \xe0 l’int\xe9rieur des canalisations."},{title:"Entretien des \xe9quipements",body:"Curage, nettoyage de bacs \xe0 graisse, pompage des eaux us\xe9es et vidange de fosse septique selon installation."},{title:"R\xe9paration et cr\xe9ation de r\xe9seau",body:"Remplacement de canalisations, cr\xe9ation de r\xe9seau et assainissement individuel non collectif selon le projet."}],detail:[{title:"Localiser avant d’intervenir",body:"Les points de refoulement, les acc\xe8s et les plans disponibles permettent de pr\xe9parer le diagnostic. Une inspection cam\xe9ra peut compl\xe9ter l’analyse lorsque la configuration l’exige."},{title:"Adapter le nettoyage",body:"Le mat\xe9riau, le diam\xe8tre et l’\xe9tat du r\xe9seau d\xe9terminent la m\xe9thode. Une canalisation fragile ne se traite pas comme un collecteur en bon \xe9tat."},{title:"Pr\xe9voir la suite",body:"Si un d\xe9faut structurel est observ\xe9, les possibilit\xe9s de r\xe9paration sont expliqu\xe9es. Pour les installations individuelles, les contraintes et d\xe9marches du projet sont \xe9tudi\xe9es s\xe9par\xe9ment."}],faq:[{q:"Intervenez-vous en copropri\xe9t\xe9 ?",a:"Oui. Le gestionnaire peut communiquer les acc\xe8s, les parties concern\xe9es et les informations connues sur le r\xe9seau."},{q:"D\xe9bouchage et curage sont-ils identiques ?",a:"Le d\xe9bouchage traite une obstruction ; le curage nettoie les d\xe9p\xf4ts du r\xe9seau. Le diagnostic permet de choisir l’intervention utile."}]},{slug:"renovation-salle-de-bain",title:"Une salle de bains \xe0 votre image.",family:"Plomberie",eyebrow:"R\xc9NOVATION & AM\xc9NAGEMENT",lead:"Du premier plan aux derniers raccordements : composer une salle de bains adapt\xe9e \xe0 vos usages et \xe0 votre espace.",intro:"L’esth\xe9tique d’une salle de bains repose sur une pr\xe9paration technique pr\xe9cise. Implantation, arriv\xe9e d’eau, \xe9vacuation, \xe9tanch\xe9it\xe9 et acc\xe8s de maintenance sont \xe9tudi\xe9s avant de fixer les choix de finition.",image:"/btm-fun/assets/vanity.webp",offers:[{title:"Douche et baignoire",body:"Adapter les \xe9quipements au volume, \xe0 l’\xe9vacuation et \xe0 vos habitudes."},{title:"Meubles et vasques",body:"Pr\xe9parer les raccordements, les fixations et les espaces de rangement."},{title:"Robinetterie et sanitaires",body:"Choisir un ensemble compatible avec les r\xe9seaux et les implantations."},{title:"Finitions coordonn\xe9es",body:"Pr\xe9parer les reprises et les \xe9tapes du chantier selon le p\xe9rim\xe8tre convenu."}],detail:[{title:"Partir de votre quotidien",body:"Rangement, facilit\xe9 d’entretien, circulation et confort d’utilisation guident le projet. Les dimensions et contraintes sont relev\xe9es avant le choix d\xe9finitif des \xe9quipements."},{title:"Pr\xe9voir les \xe9l\xe9ments invisibles",body:"La pente des \xe9vacuations, l’\xe9tanch\xe9it\xe9 et l’acc\xe8s aux organes d’arr\xeat doivent rester coh\xe9rents avec l’am\xe9nagement. Une douche de plain-pied n\xe9cessite une faisabilit\xe9 v\xe9rifi\xe9e."},{title:"Une r\xe9ception attentive",body:"Les \xe9quipements sont test\xe9s apr\xe8s raccordement. L’\xe9coulement, les joints accessibles et les commandes sont contr\xf4l\xe9s avant la prise en main de la pi\xe8ce."}],faq:[{q:"Peut-on conserver une partie de la salle de bains ?",a:"Oui, selon l’\xe9tat des \xe9quipements et la compatibilit\xe9 des nouvelles implantations. Le p\xe9rim\xe8tre de r\xe9novation est d\xe9fini au d\xe9part."},{q:"Puis-je montrer une image d’inspiration ?",a:"Oui. Elle aide \xe0 discuter du style, mais la faisabilit\xe9 technique et les dimensions doivent \xeatre v\xe9rifi\xe9es sur place."}]}],s=[{title:"Plomberie",slug:"plomberie",icon:"water",description:"D\xe9pannage, sanitaires et r\xe9novation. Tout commence par une installation fiable."},{title:"Chauffage",slug:"chauffage",icon:"heat",description:"Installation, entretien et r\xe9gulation. Le confort pens\xe9 pour votre logement."},{title:"Climatisation",slug:"climatisation-paris",icon:"cool",description:"Rafra\xeechir, chauffer, entretenir. Une solution adapt\xe9e \xe0 chaque espace."},{title:"Assainissement",slug:"assainissement",icon:"drain",description:"D\xe9bouchage, curage et inspection. Des r\xe9seaux qui fonctionnent durablement."}],n=[{slug:"projet-baignoire-ilot",title:"La baignoire, pi\xe8ce ma\xeetresse.",category:"Salles de bains",image:"/btm-fun/assets/bath.webp",caption:"Baignoire \xeelot & robinetterie noire",lead:"Une baignoire aux lignes douces, une robinetterie sur pied et un mur de carreaux blancs : les contrastes donnent du caract\xe8re \xe0 cette salle de bains.",details:["Baignoire ind\xe9pendante et circulation autour de l’\xe9quipement.","Robinetterie noire sur colonne, au plus pr\xe8s de la baignoire.","Carrelage mural blanc et joints graphiques."]},{slug:"projet-meuble-vasque",title:"Un espace pour chaque chose.",category:"Salles de bains",image:"/btm-fun/assets/vanity.webp",caption:"Meuble vasque & finitions murales",lead:"Un meuble suspendu, une vasque et des rev\xeatements coordonn\xe9s composent un espace pratique, ouvert et facile \xe0 utiliser.",details:["Meuble vasque suspendu avec rangement int\xe9gr\xe9.","Raccordements organis\xe9s sous le lavabo.","Finitions murales coordonn\xe9es autour de l’\xe9quipement."]},{slug:"projet-douche",title:"Un ensemble harmonieux.",category:"Salles de bains",image:"/btm-fun/assets/shower.webp",caption:"R\xe9novation d’une salle de bains",lead:"Une salle de bains renouvel\xe9e o\xf9 les \xe9quipements sanitaires et les finitions trouvent leur place dans un espace existant.",details:["Implantation des \xe9quipements dans la pi\xe8ce.","Robinetterie et \xe9l\xe9ments sanitaires coordonn\xe9s.","Finitions adapt\xe9es \xe0 l’usage d’une pi\xe8ce d’eau."]},{slug:"projet-wc",title:"Le soin jusque dans les petits espaces.",category:"Sanitaires",image:"/btm-fun/assets/wc.webp",caption:"WC & rangement int\xe9gr\xe9",lead:"Des sanitaires r\xe9nov\xe9s, des carreaux graphiques et une \xe9tag\xe8re int\xe9gr\xe9e : un petit espace trait\xe9 avec attention.",details:["\xc9quipement WC et finitions murales.","\xc9tag\xe8re int\xe9gr\xe9e au-dessus des sanitaires.","Coordination du carrelage et de la peinture."]},{slug:"projet-salle-de-bain",title:"Une pi\xe8ce d’eau repens\xe9e.",category:"Salles de bains",image:"/btm-fun/assets/bathroom.webp",caption:"Installation de salle de bains",lead:"L’installation des \xe9quipements sanitaires prend place dans une salle de bains aux finitions sobres.",details:["\xc9quipements adapt\xe9s \xe0 l’implantation existante.","Raccordements d’alimentation et d’\xe9vacuation.","Finitions autour des appareils sanitaires."]},{slug:"projet-finitions",title:"Les finitions font l’ensemble.",category:"Salles de bains",image:"/btm-fun/assets/tiles.webp",caption:"Am\xe9nagement & finitions",lead:"Un aper\xe7u du travail d’am\xe9nagement pr\xe9sent\xe9 dans la galerie de r\xe9alisations de BTM-PRO.",details:["Association des \xe9quipements et des rev\xeatements.","Traitement des zones humides et des raccordements.","Attention port\xe9e aux d\xe9tails de l’am\xe9nagement."]}],o=[{q:"Comment faire une premi\xe8re demande ?",a:"Choisissez votre besoin, indiquez votre code postal et votre t\xe9l\xe9phone. Une description ou une photo est facultative. Pour une urgence r\xe9elle, le t\xe9l\xe9phone reste le moyen le plus direct."},{q:"Un devis est-il pr\xe9sent\xe9 avant les travaux ?",a:"La solution et les conditions d’intervention sont expliqu\xe9es avant de commencer. Le devis est soumis \xe0 votre accord."},{q:"Intervenez-vous dans tout Paris ?",a:"Les vingt arrondissements figurent dans la couverture de BTM-PRO. Pour une adresse en \xcele-de-France, contactez l’\xe9quipe afin de confirmer la disponibilit\xe9."},{q:"Puis-je demander un projet de r\xe9novation complet ?",a:"Oui. Pr\xe9cisez les pi\xe8ces et \xe9quipements concern\xe9s pour pr\xe9parer un \xe9change sur les besoins, les contraintes et les \xe9tapes du projet."},{q:"La demande confirme-t-elle une intervention ?",a:"Non. Une demande ouvre un \xe9change. Le cr\xe9neau, le prix et le p\xe9rim\xe8tre des travaux sont confirm\xe9s ensuite."},{q:"Quels renseignements sont utiles pour un d\xe9pannage ?",a:"Le probl\xe8me observ\xe9, le type d’\xe9quipement et votre code postal. La r\xe9f\xe9rence du mod\xe8le et une photo peuvent compl\xe9ter ces renseignements."}],r=["Louvre \xb7 Palais-Royal","Bourse \xb7 Montorgueil","Temple \xb7 Arts-et-M\xe9tiers","H\xf4tel-de-Ville \xb7 Saint-Paul","Panth\xe9on \xb7 Jardin des Plantes","Saint-Germain \xb7 Luxembourg","Invalides \xb7 Gros-Caillou","Europe \xb7 Champs-\xc9lys\xe9es","Op\xe9ra \xb7 Saint-Georges","Saint-Vincent-de-Paul \xb7 Porte-Saint-Denis","Bastille \xb7 Saint-Ambroise","Bercy \xb7 Picpus","Gobelins \xb7 Maison-Blanche","Montparnasse \xb7 Petit-Montrouge","Vaugirard \xb7 Grenelle","Auteuil \xb7 Passy","Batignolles \xb7 Ternes","Montmartre \xb7 Clignancourt","Buttes-Chaumont \xb7 La Villette","Belleville \xb7 Charonne"],l=e=>`plombier-paris-${String(e).padStart(2,"0")}`}}]);